def test_config_defaults_and_repr() -> None:
    config = TracingConfig(
        service_name="svc",
        headers={"Authorization": "Bearer abc", "x-org": "o"},
        propagators=["tracecontext"],
        tls=TlsConfig(),
    )
    assert config.protocol == "http/protobuf"
    assert config.sampler == "parentbased_always_on"
    assert config.sampler_ratio == 1.0
    assert config.propagators == ("tracecontext",)
    assert config.compression == "gzip"
    assert config.set_global is True
    assert config.batch == SpanBatchOptions(2048, 512, 5.0, 30.0)
    text = repr(config)
    assert "Bearer abc" not in text
    assert "x-org" in text
    config.validate()
    assert config.with_changes(sampler="always_off").sampler == "always_off"


