def test_build_propagator() -> None:
    composite = build_propagator(["tracecontext", "baggage", "b3", "b3multi"])
    fields = composite.fields
    assert {"traceparent", "baggage", "b3", "x-b3-traceid"} <= set(fields)
    custom = build_propagator(["datadog"], {"datadog": TraceContextTextMapPropagator})
    assert "traceparent" in custom.fields
    with pytest.raises(ConfigError, match="sw8"):
        build_propagator(["sw8"])


def test_build_resource() -> None:
    config = TracingConfig(
        service_name="svc",
        service_version="1.2.3",
        environment="staging",
        resource_attributes={"team": "core", "service.name": "ignored"},
    )
    attrs = build_resource(config).attributes
    assert attrs["service.name"] == "svc"
    assert attrs["service.version"] == "1.2.3"
    assert attrs["deployment.environment"] == "staging"
    assert attrs["deployment.environment.name"] == "staging"
    assert attrs["team"] == "core"
    assert "telemetry.sdk.language" in attrs
    minimal = build_resource(TracingConfig(service_name="svc")).attributes
    assert "service.version" not in minimal
    assert "deployment.environment.name" not in minimal


def test_protocol_and_propagators_unset_markers() -> None:
    unset = TracingConfig(service_name="svc")
    assert unset.protocol == "http/protobuf"
    assert unset.propagators == ("tracecontext", "baggage")
    assert (unset.protocol, unset.propagators) == (
        DEFAULT_TRACE_PROTOCOL,
        DEFAULT_TRACE_PROPAGATORS,
    )
    assert not unset.protocol_set
    assert not unset.propagators_set
    assert "protocol='http/protobuf'" in repr(unset)
    assert "propagators=('tracecontext', 'baggage')" in repr(unset)
    # the marker travels with the value: copies keep an unset field unset
    for copy in (
        unset.with_changes(endpoint="http://collector:4318"),
        dataclasses.replace(unset, service_name="other"),
        TracingConfig(**{f.name: getattr(unset, f.name) for f in dataclasses.fields(unset)}),
        TracingConfig(service_name="svc", protocol=None, propagators=None),  # type: ignore[arg-type]
    ):
        assert not copy.protocol_set and not copy.propagators_set
    # field defaults still compare equal to the plain values (services read them)
    defaults = {f.name: f.default for f in dataclasses.fields(TracingConfig)}
    assert defaults["protocol"] == "http/protobuf"
    assert tuple(defaults["propagators"]) == ("tracecontext", "baggage")  # type: ignore[arg-type]
    explicit = TracingConfig(service_name="svc", protocol="http/protobuf", propagators=["b3"])
    assert explicit.protocol_set and explicit.propagators_set
    assert explicit.propagators == ("b3",)
    assert explicit == TracingConfig(service_name="svc", propagators=("b3",))  # markers ignored
    assert explicit.with_changes(service_name="x").protocol_set
    grpc = unset.with_changes(protocol="grpc")
    assert grpc.protocol == "grpc" and grpc.protocol_set and not grpc.propagators_set


def test_init_tracing_exports_through_factory() -> None:
    exporter = InMemorySpanExporter()
    seen: list[TracingConfig] = []

    def factory(config: TracingConfig) -> SpanExporter:
        seen.append(config)
        return exporter

    extra: list[str] = []

    class Recorder(SpanProcessor):
        def on_end(self, span: ReadableSpan) -> None:
            extra.append(span.name)

    config = TracingConfig(service_name="svc", set_global=False)
    handle = init_tracing_with(config, factory, span_processors=[Recorder()])
    assert seen == [config]
    assert handle.is_global is False
    with handle.tracer("t", "1.0").start_as_current_span("work"):
        pass
    handle.force_flush(timedelta(seconds=5))
    handle.force_flush()
    assert [s.name for s in exporter.spans] == ["work"]
    assert exporter.spans[0].service_name == "svc"
    assert extra == ["work"]
    with handle:
        pass
    assert handle.is_shut_down
    handle.shutdown()
    assert exporter.shutdown_calls == 1


def test_init_tracing_sampler_override() -> None:
    config = TracingConfig(service_name="svc", sampler="always_on", set_global=False)
    handle = init_tracing_with(config, lambda c: InMemorySpanExporter(), sampler=ALWAYS_OFF)
    assert handle.tracer_provider.sampler is ALWAYS_OFF
    with handle.tracer("t").start_as_current_span("dropped") as span:
        assert not span.is_recording()
    handle.shutdown()
    default = init_tracing_with(config, lambda c: InMemorySpanExporter())
    assert default.tracer_provider.sampler is ALWAYS_ON
    default.shutdown()


def test_force_flush_timeout() -> None:
    class Slow(SpanExporter):
        def export(self, spans: object) -> SpanExportResult:
            return SpanExportResult.SUCCESS

    handle = init_tracing_with(
        TracingConfig(service_name="svc", set_global=False), lambda c: Slow()
    )

    class Stuck(SpanProcessor):
        def force_flush(self, timeout_millis: int = 30000) -> bool:
            return False

    handle.tracer_provider.add_span_processor(Stuck())
    with pytest.raises(TimeoutError):
        handle.force_flush(0.01)
    handle.shutdown()


