@pytest.mark.usefixtures("reset_globals")
def test_init_tracing_sets_globals() -> None:
    otel_trace._TRACER_PROVIDER_SET_ONCE = Once()
    otel_trace._TRACER_PROVIDER = None
    exporter = InMemorySpanExporter()
    handle = init_tracing_with(TracingConfig(service_name="global-svc"), lambda c: exporter)
    assert handle.is_global
    assert otel_trace.get_tracer_provider() is handle.tracer_provider
    assert propagate.get_global_textmap() is handle.propagator
    second = init_tracing_with(TracingConfig(service_name="other"), lambda c: exporter)
    assert second.is_global is False  # the OTel API allows one global provider
    handle.shutdown()
    second.shutdown()


def test_init_memory_tracing_helper() -> None:
    handle, _, query = init_memory_tracing("helper-svc")
    handle.tracer_provider.add_span_processor(SimpleSpanProcessor(InMemorySpanExporter()))
    with handle.tracer("t").start_as_current_span("x"):
        pass
    handle.force_flush(5)
    assert query.list_services() == ["helper-svc"]
    handle.shutdown()
